  KEY `paymentowners_ibfk_1_idx` (`OwnerId`),
  CONSTRAINT `paymentowners_ibfk_1` FOREIGN KEY (`OwnerId`) REFERENCES `owners` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
